-- Gerado por scripts/insert_natal_deco.mjs — "Gorro Porta-bombom" (rascunho, família Decoração)
insert into prod_designs (id, nome, descricao, familia, estado, acesso_maker, disponivel_consumidor, capa_familia, usa_modo, tags, preco_creditos, scad_template, generation_schema, parametros_default)
values ('gorro_bombom', 'Gorro Porta-bombom', 'Gorro de Natal com pompom que se põe por cima de um bombom (tipo Ferrero Rocher), e base canelada onde o bombom assenta. Lembrança de Natal para a mesa ou para oferecer.', 'Decoração', 'rascunho', 'gratuito', false, false, false,
  array['gorro', 'bombom', 'ferrero', 'natal', 'mesa', 'lembrança'], 1, $tpl$// Gorro Porta-bombom — o modelo está em templates/decoracao/partes/gorro_bombom.scad (backend)
include </app/templates/decoracao/gorro_bombom.scad>
$tpl$, '{"engine":"openscad","version":1,"parameters":{"deco":{"order":0,"default":"gorro_bombom","ui":{"widget":"hidden"}},"diametro_bombom":{"order":1,"type":"number","min":18,"max":50,"unit":"mm","default":31,"ui":{"label":"Diâmetro do bombom","widget":"slider","step":0.5}},"altura":{"order":2,"type":"number","min":25,"max":100,"unit":"mm","default":45,"ui":{"label":"Altura do gorro","widget":"slider","step":1}},"estrias":{"order":3,"type":"number","min":12,"max":60,"default":28,"ui":{"label":"Número de estrias da dobra","widget":"slider","step":1}},"pompom":{"order":4,"type":"boolean","default":true,"ui":{"label":"Pompom","widget":"checkbox"}},"pecas":{"order":5,"default":"Gorro e base","ui":{"label":"Peças","widget":"select","options":["Gorro e base","Só o gorro","Só a base"]}},"info_gorro":{"order":99,"default":null,"ui":{"widget":"info","text":"🎅 31 mm é o tamanho de um Ferrero Rocher. O gorro e a base saem lado a lado: imprime o gorro a vermelho e a base a branco (ou troca de cor por cima da dobra canelada). Sem suportes."}}}}'::jsonb, '{}'::jsonb)
on conflict (id) do update set nome = excluded.nome, descricao = excluded.descricao, tags = excluded.tags,
  scad_template = excluded.scad_template, generation_schema = excluded.generation_schema;
